<?php

declare(strict_types=1);

namespace CookieConsentManager\Front;

/**
 * The embeddable iframes of the media services. A host alone is not enough: google.com also
 * serves reCAPTCHA frames, so each rule carries the path prefixes of the embed endpoints.
 *
 * Two sources: the endpoints that the vendored fragment of each service builds (Resources/catalogue/embed-rules.json,
 * generated by tools/catalogue/embed-rules.mjs) and the reviewed rules below, which add the hosts of the embed codes
 * the vendors hand out (the fragment only knows the one it builds itself).
 */
final class EmbedRules
{
    /** @var array<string, array<string, list<string>>>|null */
    private static ?array $rules = null;

    /** @var array<string, array<string, list<string>>> service key => host => path prefixes */
    public const REVIEWED = [
        'youtube' => [
            'www.youtube.com' => ['/embed/'],
            'youtube.com' => ['/embed/'],
            'www.youtube-nocookie.com' => ['/embed/'],
            'youtube-nocookie.com' => ['/embed/'],
        ],
        'vimeo' => ['player.vimeo.com' => ['/video/']],
        'dailymotion' => [
            'www.dailymotion.com' => ['/embed/'],
            'geo.dailymotion.com' => ['/player'],
        ],
        'maps_noapi' => [
            'www.google.com' => ['/maps/embed', '/maps?'],
            'maps.google.com' => ['/maps'],
        ],
    ];

    /** @return array<string, array<string, list<string>>> service key => host => path prefixes */
    public static function rules(): array
    {
        if (null === self::$rules) {
            $file = __DIR__.'/../Resources/catalogue/embed-rules.json';
            $derived = is_file($file) ? (json_decode((string) file_get_contents($file), true, 512, \JSON_THROW_ON_ERROR)['rules'] ?? []) : [];
            $rules = $derived;
            foreach (self::REVIEWED as $key => $hosts) {
                foreach ($hosts as $host => $prefixes) {
                    $rules[$key][$host] = array_values(array_unique([...($rules[$key][$host] ?? []), ...$prefixes]));
                }
            }
            self::$rules = $rules;
        }

        return self::$rules;
    }

    /**
     * The most specific rule wins (the longest path prefix): the playlist of YouTube and a single video share a host.
     *
     * @param list<string> $activeKeys keys of the media services active and published
     */
    public static function serviceFor(string $src, array $activeKeys): ?string
    {
        $parts = parse_url(str_starts_with($src, '//') ? 'https:'.$src : $src);
        if (!\is_array($parts) || !isset($parts['host']) || !\in_array($parts['scheme'] ?? 'https', ['http', 'https'], true)) {
            return null;
        }

        $host = strtolower($parts['host']);
        $path = ($parts['path'] ?? '/').(isset($parts['query']) ? '?'.$parts['query'] : '');

        $best = null;
        $bestLength = -1;
        foreach (self::rules() as $key => $hosts) {
            if (!\in_array($key, $activeKeys, true) || !isset($hosts[$host])) {
                continue;
            }
            foreach ($hosts[$host] as $prefix) {
                if (str_starts_with($path, $prefix) && \strlen($prefix) > $bestLength) {
                    $best = $key;
                    $bestLength = \strlen($prefix);
                }
            }
        }

        return $best;
    }
}
